/* ⚠ exceptionDetails 挂在 **r.result** 上，不是 r 上！
   原写法 `r.exceptionDetails` 永远 undefined → 页内异常一个都检测不到 → 返回 undefined →
   调用方 JSON.parse(undefined) 抛「"undefined" is not valid JSON」，把真正的错盖掉。
   bf-12 实测：真正的错是 canvas 被 art/*.png taint 后 getImageData 抛 SecurityError。 */
const ex = r && r.result && r.result.exceptionDetails;
if (ex) return "EXC:" + ((ex.exception || {}).description || ex.text || "");

const FILE_BASE = "file:///" + OUT.replace(/\\/g, "/").split("/").map(encodeURIComponent).join("/");
/* bf-12：默认改成**本地 HTTP**（http://127.0.0.1:8000，与 tools/bf/e2e-audio.js 同一口径）。
   原因是实测出来的：file:// 下 art/*.png 与页面**不同源**，画进 canvas 会把它 taint 掉，
   于是「读 canvas 像素」那一步的 getImageData 抛 SecurityError → 模式 A 必然降级（与好感无关的第二条根因）。
   HTTP 下同源，像素读得到。服务器没起就回落到 file:// —— 其余步骤照跑，只有读像素那条会如实失败。 */
let BASE = FILE_BASE;
function pickBase() {
  return new Promise(res => {
    const want = process.env.BF_BASE || "http://127.0.0.1:8000";
    const r = http.get(want + "/index.html", resp => { resp.resume(); res(resp.statusCode === 200 ? want : FILE_BASE); });
    r.on("error", () => res(FILE_BASE));
    r.setTimeout(3000, () => { try { r.destroy(); } catch (e) {} res(FILE_BASE); });
  });
}

if (!fs.existsSync(SHOT_DIR)) fs.mkdirSync(SHOT_DIR, { recursive: true });
BASE = await pickBase();
console.log("[基准] 页面基地址 = " + BASE + (BASE === FILE_BASE ? "（本地 HTTP 没起，回落 file:// —— 读像素那条会失败）" : "（本地 HTTP，canvas 同源可读像素）"));
let mode = "chrome-cdp", checks = [], errors = [], info = {}, extraNote = "";
